//! No matched value leaves the process. Generated secrets and embeddings are
//! placed in files, a staged git repository, and stdin; every output path of
//! both binaries (stdout, stderr, cache database bytes, baseline file) is
//! searched for the generated bytes and for runs of printed floats. Failure
//! messages name the output and the secret kind, never the value.

use regex::bytes::Regex;
use riskgrep_core::synth::{self, FloatStyle, FAKE_SECRET_KINDS};
use std::fs;
use std::io::Write;
use std::path::{Path, PathBuf};
use std::process::{Command, Stdio};
use std::sync::OnceLock;

struct World {
    home: tempfile::TempDir,
    work: PathBuf,
    _work_tmp: tempfile::TempDir,
    /// (kind, needles): byte strings that must never appear in any output.
    needles: Vec<(String, Vec<u8>)>,
    files: Vec<PathBuf>,
}

fn target_bin(name: &str) -> PathBuf {
    static BUILD: OnceLock<()> = OnceLock::new();
    let manifest = Path::new(env!("CARGO_MANIFEST_DIR"));
    let target = std::env::var_os("CARGO_TARGET_DIR")
        .map(PathBuf::from)
        .unwrap_or_else(|| manifest.join("../../target"));
    BUILD.get_or_init(|| {
        let cargo = std::env::var_os("CARGO").unwrap_or_else(|| "cargo".into());
        let st = Command::new(cargo)
            .args(["build", "--workspace", "--bins"])
            .current_dir(manifest)
            .env("CARGO_TARGET_DIR", &target)
            .status()
            .expect("cargo build");
        assert!(st.success(), "cargo build --workspace --bins failed");
    });
    target.join("debug").join(name)
}

struct Out {
    label: String,
    stdout: Vec<u8>,
    stderr: Vec<u8>,
}

fn env_for(c: &mut Command, home: &Path, dir: &Path) {
    c.current_dir(dir)
        .env("HOME", home)
        .env("XDG_CACHE_HOME", home.join(".cache"))
        .env("XDG_CONFIG_HOME", home.join(".config"))
        .env("GIT_CONFIG_NOSYSTEM", "1")
        .env("GIT_CONFIG_GLOBAL", "/dev/null")
        .env("GIT_CEILING_DIRECTORIES", dir.parent().unwrap())
        .env_remove("GIT_DIR")
        .env_remove("GIT_WORK_TREE")
        .env_remove("GIT_INDEX_FILE");
}

impl World {
    fn run(&self, label: &str, bin: &str, dir: &Path, args: &[&str], stdin: &[u8]) -> Out {
        let mut c = Command::new(target_bin(bin));
        env_for(&mut c, self.home.path(), dir);
        let mut child = c
            .args(args)
            .stdin(Stdio::piped())
            .stdout(Stdio::piped())
            .stderr(Stdio::piped())
            .spawn()
            .unwrap();
        let mut si = child.stdin.take().unwrap();
        let data = stdin.to_vec();
        let t = std::thread::spawn(move || {
            let _ = si.write_all(&data);
        });
        let o = child.wait_with_output().unwrap();
        t.join().unwrap();
        Out {
            label: label.to_string(),
            stdout: o.stdout,
            stderr: o.stderr,
        }
    }

    fn hook(&self, label: &str, dir: &Path, tool: &str, input: serde_json::Value) -> Out {
        let msg = serde_json::json!({
            "hook_event_name": "PreToolUse",
            "tool_name": tool,
            "tool_input": input,
            "cwd": dir,
        });
        self.run(
            label,
            "riskgrep-claude",
            dir,
            &[],
            msg.to_string().as_bytes(),
        )
    }
}

fn contains(hay: &[u8], needle: &[u8]) -> bool {
    !needle.is_empty() && hay.windows(needle.len()).any(|w| w == needle)
}

fn needles_for(kind: &str, secret: &str) -> Vec<NeedlePair> {
    let mut v: Vec<Vec<u8>> = vec![secret.as_bytes().to_vec()];
    for line in secret.lines().filter(|l| l.len() >= 16) {
        v.push(line.as_bytes().to_vec());
    }
    if let (Some(a), Some(b)) = (secret.find('"'), secret.rfind('"')) {
        if b > a + 1 {
            v.push(secret.as_bytes()[a + 1..b].to_vec());
        }
    }
    v.into_iter().map(|n| (kind.to_string(), n)).collect()
}

type NeedlePair = (String, Vec<u8>);

fn git(dir: &Path, home: &Path, args: &[&str]) {
    let mut c = Command::new("git");
    env_for(&mut c, home, dir);
    let out = c.args(args).output().unwrap();
    assert!(
        out.status.success(),
        "git {args:?}: {}",
        String::from_utf8_lossy(&out.stderr)
    );
}

fn world() -> &'static World {
    static W: OnceLock<World> = OnceLock::new();
    W.get_or_init(|| {
        let home = tempfile::tempdir().unwrap();
        let cfg = home.path().join(".config/riskgrep");
        fs::create_dir_all(&cfg).unwrap();
        fs::write(
            cfg.join("config.toml"),
            "[claude_code]\ntime_budget_ms = 600000\n",
        )
        .unwrap();

        let tmp = tempfile::tempdir().unwrap();
        let work = fs::canonicalize(tmp.path()).unwrap().join("work");
        fs::create_dir(&work).unwrap();

        let mut needles = Vec::new();
        let mut files = Vec::new();
        for (i, kind) in FAKE_SECRET_KINDS.iter().enumerate() {
            let secret = synth::fake_secret(kind, 1000 + i as u64);
            let body = format!("one\ntwo\nthree\n{secret}\nfive\n");
            let p = work.join(format!("{kind}.txt"));
            fs::write(&p, body).unwrap();
            files.push(p);
            needles.extend(needles_for(kind, &secret));
        }
        let floats = synth::printed_floats(256, FloatStyle::JsonArray);
        let p = work.join("embedding.json");
        fs::write(&p, &floats).unwrap();
        files.push(p);
        let st = synth::safetensors(&[
            ("speaker_embedding", "F32", &[1, 192]),
            ("other", "F32", &[1, 128]),
        ]);
        // First 24 bytes of tensor data, after the 8-byte length and header.
        let hlen = u64::from_le_bytes(st[..8].try_into().unwrap()) as usize;
        needles.push((
            "safetensors tensor data".to_string(),
            st[8 + hlen..8 + hlen + 24].to_vec(),
        ));
        let p = work.join("emb.safetensors");
        fs::write(&p, &st).unwrap();
        files.push(p);

        let w = World {
            home,
            work,
            _work_tmp: tmp,
            needles,
            files,
        };
        // Warm the rules cache once (a cold debug compile takes seconds).
        let warm = w.work.join("embedding.json");
        w.run(
            "warm",
            "riskgrep",
            &w.work,
            &["scan", warm.to_str().unwrap()],
            b"",
        );
        w
    })
}

fn names(files: &[PathBuf]) -> Vec<String> {
    files
        .iter()
        .map(|f| f.to_str().unwrap().to_string())
        .collect()
}

fn check(w: &World, out: &Out, float_run: &Regex, failures: &mut Vec<String>) {
    for (what, bytes) in [("stdout", &out.stdout), ("stderr", &out.stderr)] {
        check_bytes(
            w,
            &format!("{} {what}", out.label),
            bytes,
            float_run,
            failures,
        );
    }
}

fn check_bytes(
    w: &World,
    label: &str,
    bytes: &[u8],
    float_run: &Regex,
    failures: &mut Vec<String>,
) {
    for (kind, n) in &w.needles {
        if contains(bytes, n) {
            failures.push(format!("{label}: contains a generated `{kind}` value"));
        }
    }
    if float_run.is_match(bytes) {
        failures.push(format!("{label}: contains a run of 8 or more floats"));
    }
}

fn walk(dir: &Path, out: &mut Vec<PathBuf>) {
    for e in fs::read_dir(dir).unwrap() {
        let p = e.unwrap().path();
        if p.is_dir() {
            walk(&p, out);
        } else {
            out.push(p);
        }
    }
}

#[test]
fn no_value_leaves_the_process() {
    let w = world();
    let float_run = Regex::new(r"(-?\d+\.\d+[,\s\]\[]+){8,}").unwrap();
    let mut failures = Vec::new();
    let mut outs: Vec<Out> = Vec::new();

    let all = names(&w.files);
    let mut stdin_all = Vec::new();
    for f in &w.files {
        if f.extension().is_some_and(|e| e == "txt" || e == "json") {
            stdin_all.extend(fs::read(f).unwrap());
        }
    }

    // scan: files, directory, stdin, json and text.
    for fmt in ["json", "text"] {
        let mut args = vec!["scan", "--no-cache", "--format", fmt];
        args.extend(all.iter().map(String::as_str));
        outs.push(w.run(
            &format!("scan {fmt} files (no cache)"),
            "riskgrep",
            &w.work,
            &args,
            b"",
        ));
        let mut args = vec!["scan", "--format", fmt];
        args.extend(all.iter().map(String::as_str));
        outs.push(w.run(
            &format!("scan {fmt} files"),
            "riskgrep",
            &w.work,
            &args,
            b"",
        ));
        outs.push(w.run(
            &format!("scan {fmt} dir"),
            "riskgrep",
            &w.work,
            &["scan", "--format", fmt, "."],
            b"",
        ));
        outs.push(w.run(
            &format!("scan {fmt} stdin"),
            "riskgrep",
            &w.work,
            &["scan", "--format", fmt, "-"],
            &stdin_all,
        ));
        outs.push(w.run(
            &format!("scan {fmt} fail-above"),
            "riskgrep",
            &w.work,
            &[
                "scan",
                "--format",
                fmt,
                "--fail-above",
                "secret=1,biometric=1",
                ".",
            ],
            b"",
        ));
    }
    let json_scan = &outs[1];
    assert!(
        json_scan.stdout.len() > 100,
        "scan json produced no report; the guard would be vacuous"
    );
    let report = String::from_utf8_lossy(&json_scan.stdout);
    assert!(
        report.contains("secret") && report.contains("biometric"),
        "scan json reports no secret/biometric finding; the guard would be vacuous"
    );

    // baseline.
    let baseline = w.work.join("baseline.json");
    let mut args = vec!["baseline", "--out", baseline.to_str().unwrap()];
    args.extend(all.iter().map(String::as_str));
    outs.push(w.run("baseline", "riskgrep", &w.work, &args, b""));
    let baseline_bytes = fs::read(&baseline).expect("baseline file written");
    assert!(baseline_bytes.len() > 20, "baseline file is empty");
    check_bytes(
        w,
        "baseline file",
        &baseline_bytes,
        &float_run,
        &mut failures,
    );

    // rules list.
    outs.push(w.run("rules list", "riskgrep", &w.work, &["rules", "list"], b""));

    // git pre-commit in a repository with everything staged.
    let repo_tmp = tempfile::tempdir().unwrap();
    let repo = fs::canonicalize(repo_tmp.path()).unwrap().join("repo");
    fs::create_dir(&repo).unwrap();
    git(&repo, w.home.path(), &["init", "-q"]);
    git(&repo, w.home.path(), &["config", "user.name", "Test"]);
    git(
        &repo,
        w.home.path(),
        &["config", "user.email", "test@example.com"],
    );
    git(&repo, w.home.path(), &["config", "commit.gpgsign", "false"]);
    for f in &w.files {
        fs::copy(f, repo.join(f.file_name().unwrap())).unwrap();
    }
    git(&repo, w.home.path(), &["add", "--", "."]);
    for (label, args) in [
        ("git pre-commit", vec!["git", "pre-commit"]),
        (
            "git pre-commit --full-files",
            vec!["git", "pre-commit", "--full-files"],
        ),
    ] {
        outs.push(w.run(label, "riskgrep", &repo, &args, b""));
    }

    // riskgrep-claude: Read, Grep (directory), Bash.
    for f in &w.files {
        let n = f.file_name().unwrap().to_str().unwrap();
        outs.push(w.hook(
            &format!("hook Read {n}"),
            &w.work,
            "Read",
            serde_json::json!({ "file_path": f }),
        ));
        outs.push(w.hook(
            &format!("hook Bash cat {n}"),
            &w.work,
            "Bash",
            serde_json::json!({ "command": format!("cat {}", f.display()) }),
        ));
    }
    outs.push(w.hook(
        "hook Grep dir",
        &w.work,
        "Grep",
        serde_json::json!({ "pattern": "key", "path": w.work }),
    ));
    let emb = w.work.join("emb.safetensors");
    let hook_emb = w.hook(
        "hook Read emb",
        &w.work,
        "Read",
        serde_json::json!({ "file_path": emb }),
    );
    assert!(
        String::from_utf8_lossy(&hook_emb.stdout).contains("permissionDecision"),
        "hook gave no decision for the embedding; the guard would be vacuous"
    );
    outs.push(hook_emb);

    for o in &outs {
        check(w, o, &float_run, &mut failures);
    }

    // Cache database bytes (and sidecars) under the isolated HOME.
    let mut cache_files = Vec::new();
    walk(w.home.path(), &mut cache_files);
    let mut saw_db = false;
    for p in cache_files {
        let name = p.file_name().unwrap().to_string_lossy().into_owned();
        if name.starts_with("evidence.sqlite") {
            saw_db |= name == "evidence.sqlite";
            check_bytes(
                w,
                &format!("cache file {name}"),
                &fs::read(&p).unwrap(),
                &float_run,
                &mut failures,
            );
        }
    }
    assert!(saw_db, "no evidence.sqlite under the isolated HOME");

    assert!(failures.is_empty(), "leaks found:\n{}", failures.join("\n"));
}
